#!/usr/bin/env python3
# mkexfat.py - 为虚拟 U 盘预置「车机可直接识别」的 exFAT 文件系统 (纯 Python, 无第三方依赖)
#
# 用法: python3 mkexfat.py <镜像路径> <容量GB>
#
# 背景: 旧版 install.sh 只 dd 出一个全零稀疏文件, 没有文件系统。车机看到的是
#       「未格式化的盘」, 于是弹「格式化 USB 设备」且不显示容量, 必须人工点一次。
#       本脚本按 Tesla 车机自己格式化出来的布局(逐字节模板)预置:
#         - 引导区 (main + backup, 含 boot code 与校验和扇区)
#         - FAT / 分配位图 / Up-case 表 / 卷标 TESLACAM
#         - TeslaCam/{RecentClips,SavedClips,SentryClips,EncryptedClips}
#       新部署插上即可显示容量并直接开始录制; 镜像保持稀疏, 实际占用随录像增长。
#
# 模板字节取自一台真实 Model Y 车机格式化后正在使用的 86G exFAT 镜像,
# 因此目录条目的 NameHash / SetChecksum / 时间戳 / no-FAT-chain 标志与车机一致。
import base64, os, struct, sys, time

BPS, SPC = 512, 256
CSZ = BPS * SPC                       # 128 KiB / 簇
FAT_OFF, FAT_LEN, HEAP_OFF = 2048, 11008, 14336
# 固定簇布局 (与车机格式化结果一致; 簇号是逻辑编号, 不随容量变化)
CL_BITMAP, CL_TESLACAM, CL_UPCASE, CL_ROOT = 2, 3, 4, 5
CL_SUB = (6, 7, 8, 9)                # RecentClips / SavedClips / SentryClips / EncryptedClips

_TPL = base64.b64decode("")
_BOOT0_8 = _TPL[0:4608]
_UPCASE = _TPL[4608:10444]
_ROOT_META = _TPL[10444:10540]
_TC_SET = _TPL[10540:10636]
_TCDIR = _TPL[10636:11020]
UPCASE_LEN = len(_UPCASE)


def boot_checksum(region):
    """exFAT 引导区校验和: 遍历 sector 0..10, 跳过 VolumeFlags(106,107) 与 PercentInUse(112)"""
    cs = 0
    for i, b in enumerate(region[:11 * BPS]):
        if i in (106, 107, 112):
            continue
        cs = ((cs << 31) | (cs >> 1)) & 0xFFFFFFFF
        cs = (cs + b) & 0xFFFFFFFF
    return cs


def cl_off(cl):
    return (HEAP_OFF + (cl - 2) * SPC) * BPS


def pwrite(fd, data, off):
    # os.pwrite 在 Windows 上不存在; 设备(OpenWrt)有, 这里用 lseek+write 兼容两边
    os.lseek(fd, off, os.SEEK_SET)
    view = memoryview(data)
    while view:
        n = os.write(fd, view)
        if n <= 0:
            raise OSError('short write')
        view = view[n:]


def main():
    if len(sys.argv) != 3:
        print("用法: python3 mkexfat.py <镜像路径> <容量GB>", file=sys.stderr)
        return 2
    path = sys.argv[1]
    try:
        size_gb = int(sys.argv[2])
    except ValueError:
        print("容量必须是整数 GB", file=sys.stderr)
        return 2
    if size_gb < 1:
        print("容量至少 1G", file=sys.stderr)
        return 2

    # 不覆盖已有数据: 全零的旧版空盘允许补格式化, 有内容的盘一律跳过
    if os.path.exists(path):
        with open(path, 'rb') as f:
            head = f.read(4096)
        if any(head):
            print("镜像已含数据, 跳过 (不覆盖): %s" % path)
            return 0

    vol_len = size_gb * 1024 ** 3 // BPS
    cl_cnt = (vol_len - HEAP_OFF) // SPC
    bitmap_len = (cl_cnt + 7) // 8
    if bitmap_len > CSZ or cl_cnt > FAT_LEN * BPS // 4 - 2:
        # 车机同款布局(128KB 簇 + 单簇位图)最多寻址 128G。更大容量退回旧版行为:
        # 只建空白稀疏盘, 由车机自己格式化一次, 保证 --size 200 之类的用法不受影响。
        print("[警告] %dG 超出预置布局上限(128G): 只创建空白稀疏镜像, "
              "插车后仍需按提示点一次「格式化 USB 设备」" % size_gb)
        with open(path, 'wb') as f:
            f.truncate(vol_len * BPS)
        return 0

    with open(path, 'wb') as f:
        f.truncate(vol_len * BPS)
    # Windows CRT 的 os.open 默认是文本模式, 会把 0x0A 写成 0x0D0A 导致字节错位;
    # 显式加 O_BINARY (Linux 上该常量不存在, getattr 兜底)
    flags = os.O_RDWR | getattr(os, 'O_BINARY', 0)
    fd = os.open(path, flags)
    try:
        # --- 1. 引导区: 复制车机模板 sector 0..8, patch 容量/簇数/卷序列号 ---
        boot = bytearray(12 * BPS)
        boot[:9 * BPS] = _BOOT0_8
        struct.pack_into('<Q', boot, 0x48, vol_len)          # VolumeLength
        struct.pack_into('<I', boot, 0x5C, cl_cnt)           # ClusterCount
        struct.pack_into('<I', boot, 0x64, int(time.time()) & 0xFFFFFFFF)
        struct.pack_into('<H', boot, 0x6A, 0)                # VolumeFlags: 干净, 无 dirty
        boot[0x70] = 0                                       # PercentInUse
        boot[11 * BPS:12 * BPS] = b'\0' * BPS
        cs = boot_checksum(boot)
        boot[11 * BPS:12 * BPS] = struct.pack('<I', cs) * (BPS // 4)
        pwrite(fd,  bytes(boot), 0)                        # main  (sector 0..11)
        pwrite(fd,  bytes(boot), 12 * BPS)                 # backup(sector 12..23)

        # --- 2. FAT: 0/1 保留, 簇 2..9 写 EOF; 其余保持稀疏零 (=空闲) ---
        fat = struct.pack('<10I', 0xFFFFFFF8, 0xFFFFFFFF,
                          0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF,
                          0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF)
        pwrite(fd,  fat, FAT_OFF * BPS)

        # --- 3. 分配位图: 簇 2..9 已占用 (8 位全 1) ---
        pwrite(fd,  b'\xff', cl_off(CL_BITMAP))

        # --- 4. 标准 Up-case 表 ---
        pwrite(fd,  _UPCASE, cl_off(CL_UPCASE))

        # --- 5. 根目录: bitmap/upcase/label + TeslaCam 条目集 + 结束标记 ---
        rootdir = bytearray(256)
        rootdir[:96] = _ROOT_META
        struct.pack_into('<Q', rootdir, 0x18, bitmap_len)    # bitmap DataLength 随容量变
        rootdir[96:192] = _TC_SET
        pwrite(fd,  bytes(rootdir), cl_off(CL_ROOT))

        # --- 6. TeslaCam 目录: 四个子目录条目集 + 结束标记 ---
        tcdir = bytearray(len(_TCDIR) + 1)
        tcdir[:len(_TCDIR)] = _TCDIR
        pwrite(fd,  bytes(tcdir), cl_off(CL_TESLACAM))

        # 四个子目录内容全 0 = 空目录, 稀疏文件天然为零, 无需写入
        os.fsync(fd)
    finally:
        os.close(fd)

    st = os.stat(path)
    phys = getattr(st, 'st_blocks', 0) * 512 / 1048576.0
    print("OK %s  %dG exFAT  vol_len=%d clusters=%d bitmap=%dB checksum=%08X  物理占用~%.1fMB"
          % (path, size_gb, vol_len, cl_cnt, bitmap_len, cs, phys))
    return 0


if __name__ == '__main__':
    sys.exit(main())
